CREATE OR REPLACE FUNCTION public.is_role_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() = '178bd57a-486c-46a5-b395-4199bde4b4f3'::uuid AND EXISTS (SELECT 1 FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL) $$;
REVOKE ALL ON FUNCTION public.is_role_owner() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_role_owner() TO authenticated,service_role;
CREATE TABLE public.role_definitions (key text PRIMARY KEY CHECK (key ~ '^[a-z][a-z0-9_]{1,63}$'), label text NOT NULL CHECK (length(trim(label)) BETWEEN 2 AND 120), description text NOT NULL DEFAULT '', builtin boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.role_definitions TO authenticated;
GRANT ALL ON public.role_definitions TO service_role;
ALTER TABLE public.role_definitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_definitions_read ON public.role_definitions FOR SELECT TO authenticated USING (true);
CREATE POLICY role_definitions_owner_insert ON public.role_definitions FOR INSERT TO authenticated WITH CHECK (public.is_role_owner() AND NOT builtin);
CREATE POLICY role_definitions_owner_update ON public.role_definitions FOR UPDATE TO authenticated USING (public.is_role_owner()) WITH CHECK (public.is_role_owner());
INSERT INTO public.role_definitions(key,label,builtin) SELECT r::text, CASE r::text WHEN 'admin' THEN 'مدير النظام' WHEN 'director' THEN 'مدير الثانوية' WHEN 'supervisor' THEN 'المراقب العام' WHEN 'teacher' THEN 'الأستاذ' WHEN 'parent' THEN 'ولي الأمر' WHEN 'student' THEN 'التلميذ' WHEN 'gate_monitor' THEN 'حارس البوابة' WHEN 'developer' THEN 'المسؤول التقني' WHEN 'class_rep' THEN 'مسؤول القسم' WHEN 'class_rep_deputy' THEN 'نائب مسؤول القسم' END,true FROM unnest(enum_range(NULL::public.app_role)) r;
CREATE TABLE public.custom_role_permissions (role_key text NOT NULL REFERENCES public.role_definitions(key), permission text NOT NULL, allowed boolean NOT NULL DEFAULT false, PRIMARY KEY(role_key,permission));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.custom_role_permissions TO authenticated;
GRANT ALL ON public.custom_role_permissions TO service_role;
ALTER TABLE public.custom_role_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY custom_permissions_read ON public.custom_role_permissions FOR SELECT TO authenticated USING (true);
CREATE POLICY custom_permissions_owner ON public.custom_role_permissions FOR ALL TO authenticated USING (public.is_role_owner()) WITH CHECK (public.is_role_owner());
CREATE TABLE public.custom_user_roles (user_id uuid NOT NULL REFERENCES public.profiles(id), role_key text NOT NULL REFERENCES public.role_definitions(key), PRIMARY KEY(user_id,role_key));
GRANT SELECT,INSERT,DELETE ON public.custom_user_roles TO authenticated;
GRANT ALL ON public.custom_user_roles TO service_role;
ALTER TABLE public.custom_user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY custom_user_roles_read ON public.custom_user_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_role_owner());
CREATE POLICY custom_user_roles_owner ON public.custom_user_roles FOR ALL TO authenticated USING (public.is_role_owner()) WITH CHECK (public.is_role_owner());
DROP POLICY "perm admin write" ON public.role_permissions;
CREATE POLICY permissions_owner_write ON public.role_permissions FOR ALL TO authenticated USING (public.is_role_owner()) WITH CHECK (public.is_role_owner());
DROP POLICY "ovr admin write" ON public.user_permission_overrides;
CREATE POLICY overrides_owner_write ON public.user_permission_overrides FOR ALL TO authenticated USING (public.is_role_owner()) WITH CHECK (public.is_role_owner());
DROP POLICY "acs admin write" ON public.access_settings;
CREATE POLICY access_owner_write ON public.access_settings FOR ALL TO authenticated USING (public.is_role_owner()) WITH CHECK (public.is_role_owner());
CREATE OR REPLACE FUNCTION public.protect_role_definition() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.key IS DISTINCT FROM OLD.key OR NEW.builtin IS DISTINCT FROM OLD.builtin THEN RAISE EXCEPTION 'لا يمكن تغيير رمز الدور أو نوعه'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_role_definition BEFORE UPDATE ON public.role_definitions FOR EACH ROW EXECUTE FUNCTION public.protect_role_definition();
CREATE OR REPLACE FUNCTION public.has_permission(_user_id uuid,_perm text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN _user_id IS NULL THEN false WHEN _perm='roles.manage' THEN _user_id='178bd57a-486c-46a5-b395-4199bde4b4f3'::uuid WHEN EXISTS(SELECT 1 FROM user_permission_overrides WHERE user_id=_user_id AND permission=_perm) THEN (SELECT allowed FROM user_permission_overrides WHERE user_id=_user_id AND permission=_perm) WHEN has_role(_user_id,'developer') OR has_role(_user_id,'admin') THEN true ELSE COALESCE((SELECT bool_or(allowed) FROM (SELECT rp.allowed FROM role_permissions rp JOIN user_roles ur ON ur.role=rp.role WHERE ur.user_id=_user_id AND rp.permission=_perm UNION ALL SELECT cp.allowed FROM custom_role_permissions cp JOIN custom_user_roles cu ON cu.role_key=cp.role_key WHERE cu.user_id=_user_id AND cp.permission=_perm) permissions),false) END $$;
REVOKE ALL ON FUNCTION public.has_permission(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_permission(uuid,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.owner_set_account_roles(_user_id uuid,_roles public.app_role[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_role_owner() THEN RAISE EXCEPTION 'إدارة الأدوار محجوزة لصاحب المؤسسة'; END IF; IF _user_id=auth.uid() THEN RAISE EXCEPTION 'لا يمكن تغيير أدوار حساب المالك من هذه الصفحة'; END IF; IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=_user_id) THEN RAISE EXCEPTION 'الحساب غير موجود'; END IF; DELETE FROM user_roles WHERE user_id=_user_id; INSERT INTO user_roles(user_id,role) SELECT _user_id,unnest(_roles) ON CONFLICT DO NOTHING; INSERT INTO profile_audit_log(user_id,action,details) VALUES(auth.uid(),'owner_set_roles',jsonb_build_object('target',_user_id,'roles',_roles)); END $$;
REVOKE ALL ON FUNCTION public.owner_set_account_roles(uuid,public.app_role[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.owner_set_account_roles(uuid,public.app_role[]) TO authenticated;
CREATE OR REPLACE FUNCTION public.audit_role_management() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN INSERT INTO profile_audit_log(user_id,action,details) VALUES(auth.uid(),'permissions_'||lower(TG_OP),jsonb_build_object('table',TG_TABLE_NAME,'old',CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,'new',CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END)); END IF; RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER audit_role_definitions AFTER INSERT OR UPDATE ON public.role_definitions FOR EACH ROW EXECUTE FUNCTION public.audit_role_management();
CREATE TRIGGER audit_custom_role_permissions AFTER INSERT OR UPDATE OR DELETE ON public.custom_role_permissions FOR EACH ROW EXECUTE FUNCTION public.audit_role_management();
CREATE TRIGGER audit_custom_user_roles AFTER INSERT OR DELETE ON public.custom_user_roles FOR EACH ROW EXECUTE FUNCTION public.audit_role_management();
CREATE TRIGGER audit_role_permissions AFTER INSERT OR UPDATE OR DELETE ON public.role_permissions FOR EACH ROW EXECUTE FUNCTION public.audit_role_management();
CREATE TRIGGER audit_user_permission_overrides AFTER INSERT OR UPDATE OR DELETE ON public.user_permission_overrides FOR EACH ROW EXECUTE FUNCTION public.audit_role_management();